def shift_letter(ch, k):
    if ch.isupper():
        return chr((ord(ch) - ord("A") + k) % 26 + ord("A"))
    if ch.islower():
        return chr((ord(ch) - ord("a") + k) % 26 + ord("a"))
    return ch


def _apply(text, key, sign):
    out, i = [], 0
    for ch in text:
        if ch.isalpha():
            out.append(shift_letter(ch, sign * (ord(key[i % len(key)].lower()) - ord("a"))))
            i += 1
        else:
            out.append(ch)
    return "".join(out)


def vigenere(text, key):
    return _apply(text, key, 1)


def unvigenere(text, key):
    return _apply(text, key, -1)


def find_shift(cipher, word):
    for k in range(26):
        if word in "".join(shift_letter(ch, -k) for ch in cipher):
            return k
    return None
